/* @lc app=leetcode id=2736 lang=kotlin */ class Solution { fun upd(t: IntArray, i0: Int, v: Int) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] = maxOf(t[it], v) } fun qry(t: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.maxOfOrNull { t[it] } ?: -1 fun maximumSumQueries(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): IntArray = nums2.distinct().sorted().let { co -> co.size.let { m -> IntArray(m + 1) { -1 }.let { t -> nums1.indices.sortedByDescending { nums1[it] }.let { pts -> IntArray(queries.size).also { ans -> queries.indices.sortedByDescending { queries[it][0] }.fold(0) { p, qi -> (p + generateSequence(p) { it + 1 }.takeWhile { it < pts.size && nums1[pts[it]] >= queries[qi][0] }.onEach { upd(t, m - co.binarySearch(nums2[pts[it]]), nums1[pts[it]] + nums2[pts[it]]) }.count()).also { ans[qi] = co.binarySearch(queries[qi][1]).let { r -> if (r >= 0) r else -r - 1 }.let { r -> if (r == m) -1 else qry(t, m - r) } } } } } } } } }